<?php require __DIR__.'/ui.php';role(['admin']);$p=db();$dir=__DIR__.'/storage/backups';if(!is_dir($dir))mkdir($dir,0775,true);
if(isset($_POST['backup'])){csrf_check();$src=__DIR__.'/storage/floragestor.sqlite';$name='backup-'.date('Ymd-His').'.sqlite';$dest=$dir.'/'.$name;if(is_file($src)&&copy($src,$dest)){$p->prepare("INSERT INTO system_backups(file_name,file_size,created_by)VALUES(?,?,?)")->execute([$name,filesize($dest),current_user()['id']??null]);flash('success','Backup criado.');}else flash('error','Não foi possível criar o backup.');go('backup-center.php');}
$rows=$p->query("SELECT * FROM system_backups ORDER BY id DESC")->fetchAll();page_head('Backup e restauração');?><div class="card"><h2>Backup do banco</h2><form method="post"><?=csrf_field()?><button class="primary" name="backup">Criar backup agora</button></form><p>A restauração deve ser feita somente em modo de manutenção e após uma segunda cópia de segurança.</p></div><div class="card"><table><tr><th>Arquivo</th><th>Tamanho</th><th>Data</th></tr><?php foreach($rows as $x):?><tr><td><?=e($x['file_name'])?></td><td><?=number_format($x['file_size']/1024,1,',','.')?> KB</td><td><?=$x['created_at']?></td></tr><?php endforeach;?></table></div><?php page_foot();?>